package com.mamtrex.hospital.billing;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="invoices") public class Invoice extends BaseEntity { private String patientId; private String invoiceNumber; private String amount; private String currency; private String status; protected Invoice(){} public Invoice(String patientId, String invoiceNumber, String amount, String currency, String status){this.patientId=patientId; this.invoiceNumber=invoiceNumber; this.amount=amount; this.currency=currency; this.status=status;} public String getPatientId(){return patientId;} public String getInvoiceNumber(){return invoiceNumber;} public String getAmount(){return amount;} public String getCurrency(){return currency;} public String getStatus(){return status;} }
